insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('scal', 'intermediate', 'module', 'm01-capillary-pressure', 1, 'Capillary pressure at an oil-water interface in a water-wet rock is defined as which quantity?', '["The difference between reservoir pressure and hydrostatic pressure at the same depth", "The pressure required to open the smallest pore throats in the rock", "The pressure of the non-wetting phase minus the pressure of the wetting phase", "The pressure of the wetting phase minus the pressure of the non-wetting phase"]'::jsonb, 2, 'Pc is defined as p_nw minus p_w, the jump across the curved interface, which is why it is non-negative on a drainage curve in a water-wet rock. Reversing the subtraction flips the sign convention, and neither depth-referenced pressures nor a single throat class defines the quantity.'),
  ('scal', 'intermediate', 'module', 'm01-capillary-pressure', 2, 'Two laboratories measure the same plug with different fluid systems. Which single quantity do the resulting capillary pressures scale with?', '["The product of interfacial tension and the cosine of the contact angle", "The interfacial tension alone, since the contact angle only matters in tight rock below about 100 md", "The cosine of the contact angle alone", "The ratio of the two fluid viscosities"]'::jsonb, 0, 'The pressure jump across a curved interface carries sigma and cos(theta) together as one lever, sigma cos(theta). Neither factor acts alone at any permeability, and viscosity is a flow property that plays no role in a static capillary measurement.'),
  ('scal', 'intermediate', 'module', 'm01-capillary-pressure', 3, 'Why does a drainage capillary pressure curve rise as water saturation falls?', '["Because interfacial tension increases as the water films thin", "Because the non-wetting phase must invade progressively smaller throats, and the pressure jump scales inversely with throat radius", "Because the contact angle opens toward 90 degrees at low saturation", "Because the remaining water becomes more compressible as it retreats into pendular rings"]'::jsonb, 1, 'The fluid pair fixes sigma cos(theta); what changes along the curve is which throats are being invaded. Smaller radii demand larger pressure jumps through the 1/r scaling, so drying the rock further always costs more. Interfacial tension, contact angle, and water compressibility do not drift with saturation in this picture.'),
  ('scal', 'intermediate', 'module', 'm01-capillary-pressure', 4, 'A pore throat ten times wider than another holds an interface of the same fluid pair. Its capillary entry pressure is:', '["One hundred times smaller, since pressure scales with the square of the radius", "Unchanged, because throat size cancels out of the pressure jump", "Ten times larger", "Ten times smaller"]'::jsonb, 3, 'Pc scales as 1/r, so widening the throat tenfold cuts the required pressure tenfold. That single power of r is why two orders of magnitude in pore size span an entire reservoir capillary curve, and why the curve reads as a pore-size distribution in pressure units.'),
  ('scal', 'intermediate', 'module', 'm01-capillary-pressure', 5, 'At Sw = 0.30 the mercury-air curve on EK3-P reads 180.18302550343515 psi while the air-brine curve on EK1-P reads 29.190762994489138 psi. What mainly explains the six-fold difference?', '["EK3-P is much tighter rock, and its 250 md against EK1-P''s 420 md at lower porosity accounts for nearly the whole factor", "The mercury system''s far larger working tension scales every pressure up; rock quality is a minor factor", "Mercury interacts with clay minerals in the plug and the reaction adds pressure", "The mercury measurement was run at an elevated laboratory temperature, which raises interfacial tension several-fold"]'::jsonb, 1, 'Mercury-air works at roughly 368 dyn/cm of sigma cos(theta) against 72 for air-brine, a fluid lever of about five, while the rock-quality lever between these plugs is only about 1.2. The fluids set the scale. No clay chemistry or temperature effect is part of the measurement physics here.'),
  ('scal', 'intermediate', 'module', 'm01-capillary-pressure', 6, 'EK1-P (420 md, phi 0.23, air-brine) and EK5-P (95 md, phi 0.16, oil-brine) post nearly identical capillary pressures at Sw = 0.30. The correct reading is:', '["The two plugs are near-twins in rock quality, matching within a few millidarcies and porosity points, which the curves confirm", "The agreement is measurement noise with no structure behind it", "Tighter rock pushes EK5-P''s curve up while its gentler fluid system pulls it down, nearly cancelling", "Both plugs were measured in the same laboratory, so their fluid systems match"]'::jsonb, 2, 'EK5-P is the tightest plug of the three and EK1-P the best rock, more than a four-fold contrast in permeability. The oil-brine system''s small working tension happens to offset the tight rock''s higher pressures at this saturation. Raw curves can agree for two different reasons, which is exactly why raw curves cannot be compared by eye.'),
  ('scal', 'intermediate', 'module', 'm01-capillary-pressure', 7, 'Which laboratory capillary pressure method destroys the plug and uses fluids least like those in the reservoir?', '["Mercury injection", "The air-brine porous plate method", "The oil-brine restored-state method", "All three methods stress the plug equally"]'::jsonb, 0, 'Mercury injection is run on a dried plug that is sacrificed, with mercury against vacuum, a system far from reservoir fluids; its compensation is speed. Air-brine keeps the plug intact with a partly representative system, and restored-state oil-brine is the slowest but closest to reservoir conditions.'),
  ('scal', 'intermediate', 'module', 'm01-capillary-pressure', 8, 'Ranked by working tension sigma cos(theta), the three Ekene plug measurements order as:', '["Air-brine highest because its contact angle is zero, then oil-brine, then mercury-air", "Mercury-air highest at roughly 368 dyn/cm, air-brine at 72, oil-brine lowest at roughly 42", "Oil-brine highest because oil wets the grains, then mercury-air, then air-brine", "All three equal, because the plugs sample the same sand"]'::jsonb, 1, 'Mercury''s 480 dyn/cm trimmed by cos 40 degrees still leads by a wide margin; air-brine works at 72 with full cosine; oil-brine''s 48 trimmed by cos 30 degrees trails at about 42. A zero contact angle maximises the cosine but cannot rescue air-brine''s smaller tension, and the rock has no vote in this ranking.'),
  ('scal', 'intermediate', 'module', 'm01-capillary-pressure', 9, 'A submitted drainage table contains a row where Pc increases as Sw increases. Which refusal does the validator return?', '["\"Duplicate Sw values.\"", "\"A capillary pressure table needs at least 3 rows.\"", "\"Pc values must not be negative.\"", "\"Pc must be non-increasing in Sw (drainage curve).\""]'::jsonb, 3, 'Monotonicity is the shape rule of a drainage curve: more water means only the larger, cheaper throats hold the non-wetting phase. The message names the physics so the user knows the objection is to direction, not formatting. The other messages fire on duplicates, short tables, and negative entries respectively.'),
  ('scal', 'intermediate', 'module', 'm01-capillary-pressure', 10, 'Which clean-up does the Pc table validator perform silently, without refusing the table?', '["It deletes any row that breaks monotonicity and continues", "It sorts rows by saturation and drops non-numeric rows", "It interpolates additional rows so every table reaches fifteen entries", "It rescales mercury measurements to their air-brine equivalent"]'::jsonb, 1, 'Row order is a reporting convention and stray text is clerical, so both are repaired without comment. Everything with physical content, a rising point above all, is refused rather than repaired, and fluid-system scaling is a separate job the validator deliberately knows nothing about.'),
  ('scal', 'intermediate', 'module', 'm01-capillary-pressure', 11, 'Why does the engine refuse a table containing a rising Pc point instead of deleting the point automatically?', '["It is evidence of a lab or transcription event only a person can diagnose; deleting it would manufacture data", "Deleting one row would always leave too few remaining rows for the downstream fitting machinery to run at all", "The engine is technically unable to modify its input arrays", "Rising points are usually correct measurements of imbibition, and the monotonicity rule exists only for compatibility with older data"]'::jsonb, 0, 'A rising point may be an imbibition excursion, a cell leak, or a mis-keyed digit, and each story calls for a different correction. Software that quietly removes the evidence chooses a story on your behalf. Row count and implementation details are not the reason, and a rising point on a drainage curve is never simply correct.'),
  ('scal', 'intermediate', 'module', 'm01-capillary-pressure', 12, 'The validator requires saturations to lie in the interval (0, 1], excluding zero. The reason is that:', '["Zero is reserved as a null marker in the data format", "The logarithm of zero saturation would crash the fitting step that follows", "Capillary pressure diverges to infinity at exactly zero water saturation and no finite number could represent it", "A drainage run cannot produce a zero-water state"]'::jsonb, 3, 'The bound encodes what a drainage measurement is. Water retreats toward an irreducible saturation, 0.25 on the Ekene design, and never to zero, so a zero-saturation row cannot be data. The asymptote sits at Swirr rather than at zero, the fit takes logarithms of pressure-derived quantities rather than saturation, and no null-marker convention is involved.'),
  ('scal', 'intermediate', 'module', 'm01-capillary-pressure', 13, 'The Ekene reservoir curve reads 0.7355825053402938 psi at Sw = 1.00. This entry pressure represents:', '["The pressure at which water reaches its irreducible saturation", "The minimum capillary pressure the non-wetting phase needs to first invade the largest throats of the rock", "The average pressure across the plateau region of the curve", "The reading the same rock would give in a mercury-air system"]'::jsonb, 1, 'At full water saturation the curve''s finite value is the price of admission through the biggest throats; below it, oil pressed against the water-full rock does not invade at all. Irreducible saturation sits at the opposite end of the curve, the plateau average is not a defined engine quantity, and a mercury-air reading of this rock would be several times larger, not sub-psi.'),
  ('scal', 'intermediate', 'module', 'm01-capillary-pressure', 14, 'Between its wet end and Sw = 0.30, the Ekene reservoir drainage curve climbs by exactly what factor?', '["About 6.2, the spread between the EK3-P mercury curve and the EK1-P air-brine curve at this same saturation", "About 1.2, the rock-quality lever between the best and mid plugs", "Fifteen, from 0.7355825053402938 psi at entry to 11.03373758010441 psi at Sw = 0.30", "About 9, the ratio between the largest and smallest working tensions across the three laboratory systems"]'::jsonb, 2, 'The reservoir curve''s own two published ends divide to exactly fifteen, a designed property of the Ekene curve shape that the J-function module will expose. The 6.2 spread compares two different plugs in different fluid systems, 1.2 is the rock lever inside that comparison, and 9 describes the tension table, none of them this curve''s climb.'),
  ('scal', 'intermediate', 'module', 'm01-capillary-pressure', 15, 'The Ekene capillary curve has its asymptote at Swirr = 0.25 while the field''s relative permeability set uses Swc = 0.35. The correct resolution is:', '["Both are right: the asymptote is the unlimited-pressure limit; the kr connate is what the rock in place drained to", "One of the two files carries a transcription error that must be fixed before either can be used", "The kr table should be shifted so that its curves start at 0.25", "The capillary measurement should be repeated with mercury injection, whose higher pressures resolve saturations below 0.30"]'::jsonb, 0, 'The two numbers answer different questions. No finite pressure dries the rock past 0.25, but no point in a finite oil column experiences unlimited pressure, so the rock as found sits wetter than the wall. Editing either dataset to match the other would destroy real information, and the choice of lab system does not change the distinction.'),
  ('scal', 'intermediate', 'module', 'm02-the-leverett-collapse', 1, 'In the Leverett J-function, permeability and porosity enter as sqrt(k/phi). What physical role does this term play?', '["It corrects the measured pressure for the compressibility of the rock frame between laboratory and reservoir stress", "It converts the pressure from laboratory temperature to reservoir temperature through the fluid expansion term", "It acts as a pore-size length scale, since sqrt(k) is a length and dividing by phi restricts it to the open rock", "It normalizes the saturation axis onto the mobile range between connate water and residual oil"]'::jsonb, 2, 'Permeability has units of area, so its square root is a length, and dividing by porosity first makes that length characterize the pores rather than the bulk rock. Smaller pores mean tighter interface curvature and higher capillary pressure at the same saturation, which is exactly the scale the J-function divides out. Saturation normalization is a separate step that uses Swirr, not k and phi.'),
  ('scal', 'intermediate', 'module', 'm02-the-leverett-collapse', 2, 'The engine''s locked golden values for the Leverett correlation were typed from the reproduction in Ahmed''s Reservoir Engineering Handbook, 4th edition, rather than from Leverett''s 1941 paper itself. Why?', '["The original Trans. AIME scan is member gated, and the fixture doctrine requires typing values from a source open on the desk", "The 1941 paper contains an arithmetic error in its correlation figure that Ahmed corrected when reprinting it in the 4th edition", "The original paper published only the imbibition branch of the correlation, and the course grades against the drainage branch", "Ahmed''s reproduction restates the correlation in field units, while the original was published in CGS units only"]'::jsonb, 0, 'The provenance note in the engine''s test suite states it directly: the original SPE-941152-G scan is behind the OnePetro paywall, so the golden was sourced from the faithful reproduction in Ahmed 4th edition, with a visible upgrade path to re-read the original if the owner supplies the PDF. Values are typed from an open source, never recalled. No arithmetic error in the original is claimed anywhere, and the 1941 figure carries both branches.'),
  ('scal', 'intermediate', 'module', 'm02-the-leverett-collapse', 3, 'Plug EK1-P (k 420 md, phi 0.23, air-brine at sigma 72 dyn/cm and theta 0) reads 29.190762994489138 psi at the 0.30 saturation row. What J value does the engine compute there?', '["0.25", "3.750000000000001", "1.25", "29.190762994489138"]'::jsonb, 1, 'J = 0.21645 x (29.190762994489138 / 72) x sqrt(420/0.23) = 3.750000000000001, the designed curve''s exact 3.75 with one bit of floating-point dust. The value 0.25 is the curve''s J at full water saturation, 1.25 is its J at the 0.40 row, and 29.19 psi is the pressure itself, which is dimensional and cannot be a J value.'),
  ('scal', 'intermediate', 'module', 'm02-the-leverett-collapse', 4, 'Deriving the field-unit J constant from exact CGS conversions gives 0.21665, yet the engine stores LEVERETT_C = 0.21645. What justifies shipping the less exact number?', '["0.21645 compensates for the average contact-angle hysteresis between drainage and imbibition measurements in unconsolidated sands", "The derivation from CGS conversions contains a known unit error in the millidarcy conversion step and 0.21645 is the corrected value", "The difference is below double precision, so the two constants are stored as the same number", "Only consistency matters: the constant cancels in the round trip, and the published value matches the printed textbooks"]'::jsonb, 3, 'The round trip from Pc to J and back uses the constant in numerator and denominator, so any consistent value cancels to 1e-12 in the engine''s tests. Adopting the constant printed in Tiab and Donaldson and in Amyx, Bass and Whiting keeps the course aligned with the literature. The two values differ by nine parts in ten thousand, far above machine precision, and neither is an error; they are a published convention and an exact derivation.'),
  ('scal', 'intermediate', 'module', 'm02-the-leverett-collapse', 5, 'For the Ekene reservoir description (k 250 md, phi 0.20, sigma 26 dyn/cm, theta 30 degrees), what is the psi-per-J factor?', '["2.942330021361175 psi per unit of J", "48.048806800916026 psi per unit of J", "22.516660498395407 psi per unit of J", "7.784203465197102 psi per unit of J"]'::jsonb, 0, 'The factor is sigma cos theta divided by LEVERETT_C times sqrt(k/phi): 22.516660498395407 / (0.21645 x sqrt(1250)) = 2.942330021361175. The value 22.5166 is just the numerator sigma cos theta before dividing, while 48.049 and 7.784 are the psi-per-J factors of the mercury plug EK3-P and the air-brine plug EK1-P respectively.'),
  ('scal', 'intermediate', 'module', 'm02-the-leverett-collapse', 6, 'Across the fifteen saturation rows, the three Ekene plugs'' computed J values agree with a maximum spread of 4.440892098500626e-16. What does this number tell you?', '["The three laboratories calibrated their pressure transducers against the same dead-weight standard within stated error", "The fitted power law explains all but 4.4e-16 of the log-space variance in the pooled saturation data", "It is machine-precision agreement: each lab table was generated from the designed curve, so the collapse is exact", "The spread equals the stated read tolerance of the published 1941 correlation figure at plate scale"]'::jsonb, 2, '4.44e-16 is machine-epsilon territory: the plugs agree to the final bit doubles can hold. That is only possible because the fixture is designed, with every lab table generated from the planted curve, so the collapse recovering it is the machinery proving itself. Real core shows percent-level scatter, and the figure-read tolerance of the published correlation is 0.05 in J, fourteen orders of magnitude larger. A variance statement would be an r-squared, which this is not.'),
  ('scal', 'intermediate', 'module', 'm02-the-leverett-collapse', 7, 'The designed Ekene J curve with a 0.25, b 1.0 and Swirr 0.25 reduces to J = 0.1875/(Sw - 0.25). What is J at a water saturation of 0.625?', '["0.25", "3.75", "1.25", "0.5"]'::jsonb, 3, 'At Sw = 0.625 the denominator is 0.375, and 0.1875/0.375 = 0.5 exactly. The other values are the curve at different waypoints: 3.75 at the 0.30 row, 1.25 at the 0.40 row, and 0.25 at full water saturation where the power law returns its own coefficient a.'),
  ('scal', 'intermediate', 'module', 'm02-the-leverett-collapse', 8, 'For a power-law J curve, what is the significance of the value J takes at a water saturation of exactly 1?', '["It is zero, since a rock at full water saturation supports no pressure difference between the phases in its pores", "It equals the coefficient a, which scaled by a rock''s psi-per-J factor becomes that rock''s entry pressure", "It equals the exponent b, which sets how steeply the curve climbs toward the irreducible asymptote", "It is infinite, since the power law diverges at the boundary of its saturation domain"]'::jsonb, 1, 'At Sw = 1 the normalized saturation is 1 and a x 1^(-b) = a, which is 0.25 on the Ekene design. Multiplying by a rock''s psi-per-J factor turns it into the entry pressure, the quantity the saturation-height module builds on. The divergence happens at the other end of the curve, as Sw approaches Swirr, and a water-full rock has zero capillary pressure only at the free water level, not as a property of the curve.'),
  ('scal', 'intermediate', 'module', 'm02-the-leverett-collapse', 9, 'The Ekene capillary design uses Swirr 0.25 while the displacement course used a connate water saturation Swc of 0.35. How should these two numbers be understood?', '["They are different statements: the drainage asymptote versus what the crest zone has actually drained to", "One of the two is a data-entry error carried over from the displacement course, since a rock has a single irreducible water saturation", "Swirr describes the laboratory plugs and Swc describes the reservoir, so the two numbers are never comparable", "The 0.10 difference is the residual oil saturation, which must be subtracted from the water endpoint before scaling"]'::jsonb, 0, 'The Pc asymptote is the saturation drainage approaches at unbounded capillary pressure, while the connate water in the kr set is what the rock at crest height has actually drained to under the finite pressure available there. Setting Swirr deliberately below Swc encodes that distinction. Residual oil is a property of the imbibition direction and has nothing to do with the gap, and both numbers describe the same rock.'),
  ('scal', 'intermediate', 'module', 'm02-the-leverett-collapse', 10, 'An analyst keys plug EK1-P''s permeability as 1680 md instead of the true 420 md, a factor of four high, and rebuilds the J table from the same pressures. What happens to the plug''s J curve?', '["It steepens at low saturation while the plateau stays fixed, changing the shape of the curve", "It rides exactly 4 times above the correct curve at every saturation row in the table", "It rides exactly 2 times above the correct curve at every saturation", "It drops below the cloud by a factor of sqrt(2) at every saturation"]'::jsonb, 2, 'Permeability enters under a square root, so the ride factor is sqrt(1680/420) = sqrt(4) = 2, identical at every row because the error is a pure multiplier with no saturation dependence. The engine''s test suite pins this exact case. A shape change cannot be produced by any scaling error, and overstating k pushes J up, not down.'),
  ('scal', 'intermediate', 'module', 'm02-the-leverett-collapse', 11, 'Plug EK1-P''s porosity, truly 0.23, is keyed as 0.32. By what factor does its J curve move, and in which direction?', '["It rides high by sqrt(0.32/0.23), about 1.18, since porosity strengthens the numerator of the scaling", "It rides low by sqrt(0.23/0.32) = 0.8477912478906585, the same factor at every row", "It is unaffected, because porosity cancels between the J computation and the psi-per-J back-scaling", "It rides low by the linear ratio 0.23/0.32, about a 28 percent depression at every saturation row"]'::jsonb, 1, 'Porosity sits in the denominator inside the square root, so overstating it shrinks sqrt(k/phi) and the whole curve rides low by sqrt(0.23/0.32) = 0.8477912478906585, about 15 percent. The linear ratio 0.719 forgets the square root, and porosity appears exactly once in the formula, so nothing cancels. Direction is diagnostic: a low-riding curve means overstated phi, understated k, or overstated sigma cos theta.'),
  ('scal', 'intermediate', 'module', 'm02-the-leverett-collapse', 12, 'A plug''s J curve CROSSES the others in the cloud: steeper at low saturation, flatter at the plateau. What does this rule out, and what does it suggest?', '["It rules out measurement error entirely and suggests the plug should anchor the family as its most representative sample", "It rules out a wrong Swirr and suggests the 0.21645 constant was applied twice during the collapse step", "It rules out a mis-typed interfacial tension and suggests the permeability entry is wrong instead", "It rules out any scaling-input error, and suggests different pore geometry or a saturation-dependent artifact"]'::jsonb, 3, 'Every scaling input, sigma, theta, k and phi, enters J as a constant multiplier, so an error in any of them moves the whole curve by one factor without bending it. A curve that changes shape relative to the family cannot be rescued by fixing an input; it is either a different rock type, a damaged plug, or an artifact that varies with saturation, and the honest response is exclusion from the family, not a fudge factor.'),
  ('scal', 'intermediate', 'module', 'm02-the-leverett-collapse', 13, 'The ratio of plug EK3-P''s raw pressures to plug EK1-P''s is 6.172604174048192 at the 0.30 row, and exactly the same at every other row. Why is the ratio constant in saturation?', '["Both plugs sit on one J curve, so the ratio is a ratio of two psi-per-J constants, with no saturation in it", "Mercury injection compresses the saturation axis by a constant factor relative to air-brine systems", "The two plugs have identical permeability, so only the constant fluid-pair ratio survives the division", "The generator rounded both tables to the same number of significant figures before committing them"]'::jsonb, 0, 'Pc equals J times the plug''s psi-per-J factor, so with a shared J curve the ratio of two plugs'' pressures is 48.048806800916026 / 7.784203465197102 = 6.172604174048192 at every saturation. The plugs'' permeabilities differ, 250 versus 420 md, and the rock factors contribute about 1.21 of the 6.17 with the fluid pair contributing about 5.1. Nothing about mercury changes the saturation axis, and no rounding is involved; the fixture carries full double precision.'),
  ('scal', 'intermediate', 'module', 'm02-the-leverett-collapse', 14, 'Plugs EK1-P and EK5-P have very different rock properties (420 versus 95 md, phi 0.23 versus 0.16) and different lab fluids, yet their raw pressure tables agree within 1.25 percent at every row. What is the correct reading?', '["The two plugs are duplicates cut from the same core barrel, and one of them should be discarded from the family", "The agreement confirms that both laboratories measured pressures to better than 2 percent absolute accuracy across the table", "It is an accident of cancellation, rock and fluid factors offsetting, so raw-psi agreement is not evidence of similarity", "The oil-brine system chemically altered plug EK5-P until its response matched the air-brine measurement"]'::jsonb, 2, 'EK5-P''s smaller sqrt(k/phi) raises its pressures by almost exactly the factor its smaller sigma cos theta lowers them, so the psi-per-J factors land within 1.0125075924228712 of each other by coincidence. Raw curves agreeing says nothing about the rocks; converted to a common fluid system the two tables would separate by the rock-factor ratio of about 1.75. This is the standing argument for comparing on the J axis, never in raw psi.'),
  ('scal', 'intermediate', 'module', 'm02-the-leverett-collapse', 15, 'Why is a booked contact angle more dangerous at 40 degrees than at 0 degrees when it carries the same 5 degree uncertainty?', '["Because interfacial tension can only be measured accurately in systems with contact angles near zero", "The error propagates through cos theta, near flat at 0 but steep at 40, moving sigma cos theta about 6 percent there", "Because contact angles above 30 degrees invalidate the Leverett collapse for the affected sample entirely", "Because at 40 degrees the wetting phase changes identity and the drainage direction reverses in the plug"]'::jsonb, 1, 'The derivative of cos theta vanishes at zero and grows with angle, so the same angular uncertainty costs little near 0 and several percent near 40. That is why a plug riding off the cloud with a large booked angle should have theta checked before the rock properties. The collapse itself remains valid at any angle below 90 provided the product sigma cos theta is right, and wettability does not flip at some threshold angle in this framework.'),
  ('scal', 'intermediate', 'module', 'm03-the-nameless-field', 1, 'For the Nameless Field lab core (k 80 md, phi 0.16, sigma 50 dyn/cm, theta 0 degrees), what is the J-per-psi factor that converts each lab Pc row into J?', '["0.21645, the Leverett constant itself", "0.0967993827459659", "9.191758209219469", "0.000193598765491932, from the square root of phi over k"]'::jsonb, 1, 'The factor is 0.21645 times the square root of k over phi, divided by sigma cos theta: 0.21645 x 22.360679774997896 / 50 = 0.0967993827459659, which Ahmed prints as 0.096799. The value 9.191758209219469 is the RESERVOIR rock''s psi-per-J factor, the conversion pointed the other way on a different rock, and the Leverett constant is only one ingredient of the factor. Using phi over k inside the square root inverts the rock term and shrinks the factor by the ratio k/phi.'),
  ('scal', 'intermediate', 'module', 'm03-the-nameless-field', 2, 'Which value does the engine''s computeJTable return for J at Sw 0.2 on the Nameless Field lab core?', '["0.16939891980544033", "0.169, the value the book itself prints for that row", "0.1016393518832642", "1.5534071373580902"]'::jsonb, 0, 'The engine multiplies the printed Pc of 1.75 psi by the full-precision factor 0.0967993827459659 and returns 0.16939891980544033. The book prints that same value rounded to three decimals as 0.169; the rounded print is what the page shows, not what the engine returns. 0.1016393518832642 is the J at Sw 0.4, and 1.5534071373580902 is a reservoir capillary pressure in psi, not a dimensionless J.'),
  ('scal', 'intermediate', 'module', 'm03-the-nameless-field', 3, 'Reading the Nameless Field J column from Sw 1.0 down to Sw 0.2, J rises from 0.048 to 0.169. What drives that rise?', '["The factor grows as saturation falls, because the rock term depends on Sw", "Interfacial tension increases as the water saturation drops", "Pc rises along the drainage curve as Sw falls, and J is proportional to Pc", "The book applies a larger rounding correction at low saturation"]'::jsonb, 2, 'On one plug the conversion factor is a single constant, so the J column inherits its shape entirely from the measured Pc curve: drainage Pc climbs from 0.50 to 1.75 psi as water is displaced toward irreducible saturation, and J is that curve rescaled. The factor contains only k, phi, sigma and theta, none of which vary with saturation, and rounding is a presentation choice, not a physical effect.'),
  ('scal', 'intermediate', 'module', 'm03-the-nameless-field', 4, 'The reservoir factor 9.191758209219469 psi per unit J is built from which inputs?', '["The lab plug''s k of 80 md and phi of 0.16, inverted", "The printed J column of step 1 together with the five measured lab Pc rows", "The Leverett constant and the reservoir pressure", "50 divided by (0.21645 times the square root of 120/0.19)"]'::jsonb, 3, 'Coming back from J to pressure uses the destination rock''s own description: 50 / (0.21645 x sqrt(120/0.19)) = 9.191758209219469, which Ahmed prints as 9.192. The lab plug''s properties built the OTHER factor, the 0.0967993827459659 per psi that made the J column in the first place. No pressure history and no Pc table enters either factor; they are pure rock and fluid constants.'),
  ('scal', 'intermediate', 'module', 'm03-the-nameless-field', 5, 'Following Ahmed''s own step 3, what reservoir Pc does the chain give at Sw 0.2?', '["1.5570739117545667 psi", "1.5534071373580902 psi", "1.75 psi", "0.9375593373403855 psi"]'::jsonb, 1, 'The book''s chain multiplies the PRINTED J of 0.169 by the reservoir factor: 0.169 x 9.191758209219469 = 1.5534071373580902 psi, printed as 1.553. The value 1.5570739117545667 is what you get by running the same chain from the full-precision J instead, a legitimate number but not the book''s chain and outside the capstone tolerance. 1.75 psi is the LAB Pc at that saturation, and 0.9375593373403855 psi belongs to Sw 0.4.'),
  ('scal', 'intermediate', 'module', 'm03-the-nameless-field', 6, 'The capstone field res_pc_sw02 is graded at a tolerance of 0.002 psi. Which chain must you run to pass it?', '["Either chain, since both round to 1.55 psi", "The full-precision chain, because grading always uses maximum precision", "The printed-J chain, multiplying 0.169 by the reservoir factor", "The lab chain, dividing the lab Pc by the lab factor"]'::jsonb, 2, 'The graded value is 1.5534071373580902 psi, produced by rescaling the J column as printed, which is what Ahmed''s solution actually does. The full-precision chain lands at 1.5570739117545667, a gap of 0.0037 psi, nearly twice the 0.002 tolerance, so it fails even though its arithmetic is perfect. The tolerance was chosen precisely so that the two chains are distinguishable; reproducing a published table means reproducing its inputs, rounding included.'),
  ('scal', 'intermediate', 'module', 'm03-the-nameless-field', 7, 'How large is the gap between the printed-J chain and the full-precision chain for reservoir Pc at Sw 0.2, and what causes it?', '["0.0037 psi, about 0.24 percent, from the print rounding of J", "0.002 psi exactly, matching the grading tolerance", "Zero, because both chains use the same reservoir factor", "About 0.2 psi, reflecting the k over phi difference between the two rocks"]'::jsonb, 0, '1.5570739117545667 minus 1.5534071373580902 is about 0.0037 psi, 0.24 percent of the value, and it comes entirely from printing J as 0.169 instead of 0.16939891980544033 before multiplying. Sharing the reservoir factor does not close the gap because the chains differ in their J input. The rock difference is not an error at all: it is the physics both chains correctly apply.'),
  ('scal', 'intermediate', 'module', 'm03-the-nameless-field', 8, 'With a contact angle of 0 degrees, what does the sigma cos theta term in the J formula evaluate to for this example?', '["1, since the cosine of zero is one and sigma cancels", "Zero, so the term drops out of the formula", "25 dyn/cm, half the interfacial tension", "50 dyn/cm, the interfacial tension unchanged"]'::jsonb, 3, 'cos(0) is 1, so sigma cos theta reduces to sigma itself, 50 dyn/cm. The term never drops out and sigma never cancels: it is the fluid-pair normalization that lets curves measured with different fluid systems land on the same J curve. A zero CONTACT ANGLE is the perfectly water-wet case, which is exactly when the correction is simplest, not absent.'),
  ('scal', 'intermediate', 'module', 'm03-the-nameless-field', 9, 'At every saturation the rebuilt reservoir Pc sits below the lab Pc (0.4412043940425345 versus 0.50 psi at Sw 1.0). Why?', '["The reservoir factor was printed at lower precision than the lab factor", "The reservoir is at higher temperature, which lowers interfacial tension", "Larger k over phi means wider pores, which hold a given saturation at lower Pc", "Reservoir Pc is always lower than lab Pc, whatever the rocks"]'::jsonb, 2, 'The fluid system is identical on both sides, so the entire shift is the rock correction: sqrt(k/phi) is larger for the reservoir rock, which puts a smaller psi-per-J factor on the same J column. Physically, more permeability per unit porosity means wider pore throats and weaker capillary rise. The direction is not universal: hand the same J column a TIGHTER rock and the rebuilt curve rises above the lab one.'),
  ('scal', 'intermediate', 'module', 'm03-the-nameless-field', 10, 'What does a value derived from a printed number carry, according to the rule this module teaches?', '["Nothing, provided the downstream arithmetic is done at full precision", "The print''s rounding, forever", "A uniform bias that can be subtracted once it is measured", "At most one unit of error in its own last digit"]'::jsonb, 1, 'Rounding is a one-way door: the full value can regenerate the print, but the print can never regenerate the full value, so every downstream result inherits the print''s truncation permanently. It is not a uniform bias, because each row rounds its own way, up at Sw 0.6 and down at Sw 0.2 in this example, so no single subtraction repairs a table. That is why every derived number should name its chain.'),
  ('scal', 'intermediate', 'module', 'm03-the-nameless-field', 11, 'What is the engine-precision J at Sw 0.6, where the lab Pc is 0.75 psi?', '["0.07259953705947443", "0.073", "0.058079629647579546", "0.6709983492730213"]'::jsonb, 0, '0.75 x 0.0967993827459659 = 0.07259953705947443, which the book prints as 0.073 after rounding UP in the third decimal. This is one of the rows where the print sits above the engine value, the opposite direction from Sw 0.2. The value 0.058079629647579546 is J at Sw 0.8, and 0.6709983492730213 is the reservoir Pc at this saturation in psi, a different quantity entirely.'),
  ('scal', 'intermediate', 'module', 'm03-the-nameless-field', 12, 'Which set of quantities, and only these, enters the J-function scaling of a capillary pressure measurement?', '["Permeability, porosity, water viscosity and oil viscosity", "Pc, saturation, and the height above the free water level", "Permeability, porosity and the depth of the sample", "Permeability, porosity, interfacial tension and contact angle"]'::jsonb, 3, 'J = 0.21645 (Pc / sigma cos theta) sqrt(k/phi): the rock enters through k and phi, the fluid pair through sigma and theta, and nothing else. Viscosities belong to flow and fractional-flow calculations, not to capillary equilibrium, and height enters only later when a Pc curve is converted to a saturation-height profile. Depth by itself has no place in the scaling at all.'),
  ('scal', 'intermediate', 'module', 'm03-the-nameless-field', 13, 'At Sw 0.8 the full-precision chain gives 0.5338539126015657 psi against the printed chain''s 0.5331219761347291, while at Sw 0.2 the printed chain is the LOWER one. What does this sign flip demonstrate?', '["The engine loses accuracy at high water saturation", "The reservoir factor was applied inconsistently between the low and high saturation rows", "Rounding error has no preferred direction; each row''s print rounded its own way", "The printed table contains a typographical error at Sw 0.8"]'::jsonb, 2, 'At Sw 0.8 the print rounded J down (0.058079629647579546 to 0.058), leaving the printed chain low, while at Sw 0.2 the print also rounded down but by a different amount, and at Sw 0.6 it rounded up. Each row takes its own coin flip at the third decimal, so the gaps alternate in sign across the table. Both chains use the identical factor on every row, and no typo is involved: this is what honest rounding looks like.'),
  ('scal', 'intermediate', 'module', 'm03-the-nameless-field', 14, 'The five lab rows run from Pc 0.50 psi at Sw 1.0 up to 1.75 psi at Sw 0.2. What property must a valid drainage Pc table have?', '["Pc non-increasing as Sw increases", "Pc proportional to Sw across the table", "Pc equal to zero at Sw 1.0", "Equal Pc steps between successive rows"]'::jsonb, 0, 'Drainage displaces the wetting phase into ever smaller pore throats, so capillary pressure can only stay level or climb as water saturation falls; read in the direction of increasing Sw, Pc must not increase. The engine''s table validator enforces exactly that monotonicity. Nothing requires proportionality or even spacing, and a nonzero entry pressure at full water saturation, 0.50 psi here, is normal: it is the pressure needed to force the first nonwetting fluid in.'),
  ('scal', 'intermediate', 'module', 'm03-the-nameless-field', 15, 'In Ahmed''s step 3, which object is rescaled to produce the reservoir Pc table?', '["The lab Pc table, converted directly with the ratio of the two factors", "The J column as printed in step 1", "The full-precision J column recomputed by the engine", "The reservoir factor itself, adjusted row by row"]'::jsonb, 1, 'The book carries its own printed, three-decimal J column into step 3 and multiplies it by 9.192; that is the chain the capstone grades. Rescaling the lab Pc directly by the factor ratio is algebraically equivalent ONLY if you keep full precision throughout, which the book does not, and the engine''s full-precision column produces the alternative chain of lesson 4. The factor is a single constant and is never adjusted per row.'),
  ('scal', 'intermediate', 'module', 'm04-fitting-and-averaging', 1, 'In the engine''s power-law form J = a (Sw*)^(-b), what does the parameter a represent?', '["The slope of the fitted straight line in log coordinates", "The value of J at full water saturation", "The value of J at the irreducible saturation, where the curve turns upward", "The lowest J value the lab measured on the plug"]'::jsonb, 1, 'At Sw = 1 the normalized saturation Sw* equals 1 and the power term vanishes, so J = a: the entry level of the curve. The log-space slope is -b, and at the irreducible saturation the curve diverges rather than taking any finite parameter value.'),
  ('scal', 'intermediate', 'module', 'm04-fitting-and-averaging', 2, 'Why does fitJPowerLaw form its residuals in the logarithm of J rather than in J itself?', '["Logarithms make the Levenberg-Marquardt kernel converge in fewer iterations", "J can be negative on the imbibition branch and the logarithm removes the sign", "The centrifuge apparatus reports its capillary pressures in logarithmic units by convention", "Log residuals weight a proportional miss equally across the wide range J spans"]'::jsonb, 3, 'A J curve can span a factor of fifteen or more between full saturation and the irreducible end. Linear residuals would let the high-J points dominate the sum of squares; the logarithm makes a 10 percent miss count the same everywhere on the curve. J must be positive for the transform, which is why non-positive rows are excluded, but that is a consequence, not the motivation.'),
  ('scal', 'intermediate', 'module', 'm04-fitting-and-averaging', 3, 'Handed one Ekene plug''s J table together with the true Swirr of 0.25, what does the power-law fit return?', '["a of 0.25 and b of 1, with a log-space r squared of exactly 1", "a of 0.25 and b of 1, with a log-space r squared of 0.9548556748366249", "a of 0.3922841458642378 and b of 0.17888262635639235", "It refuses to fit because the supplied Swirr equals the design value"]'::jsonb, 0, 'The plugs were generated from a designed power law, so the fit recovers the plant exactly and the log-space r squared is 1. The 0.9549 figure and the a 0.392 with b 0.179 pair belong to the Figure 4-18 figure-read fit, where the source is a plate read at a 0.05 tolerance, not a designed dataset.'),
  ('scal', 'intermediate', 'module', 'm04-fitting-and-averaging', 4, 'Using the recovered Ekene curve, with a of 0.25, b of 1 and Swirr of 0.25, what is J at Sw = 0.30?', '["0.25, the same as at full saturation", "0.60, read from the Leverett figure", "3.75", "15"]'::jsonb, 2, 'Sw* = (0.30 - 0.25)/0.75 = 1/15, and with b = 1 the curve is a pure reciprocal, so J = 0.25 x 15 = 3.75. The value 15 is the reciprocal of Sw* before multiplying by a, and 0.60 is the Figure 4-18 read at Sw 0.2 for a different rock family entirely.'),
  ('scal', 'intermediate', 'module', 'm04-fitting-and-averaging', 5, 'What does the power-law fit do with the irreducible saturation Swirr?', '["Fits it jointly with a and b as a third free parameter", "Treats it as an input that must sit below the lowest Sw in the data", "Reads it off the highest measured capillary pressure in the table", "Sets it to zero so that Sw* coincides with Sw"]'::jsonb, 1, 'Swirr sits inside the coordinate Sw*, so it must be known before a single residual can be formed. The fit checks that it lies below the data floor and refuses otherwise. It is never estimated by the fit itself, which is exactly why the default and the override matter.'),
  ('scal', 'intermediate', 'module', 'm04-fitting-and-averaging', 6, 'When no Swirr is supplied to the fit, what value does the engine fall back on?', '["The sample''s lowest measured Sw minus 0.02, clamped at zero", "The design value 0.25 from the fixture", "The connate water saturation from the nearest log analysis", "Zero, so the axis needs no normalization"]'::jsonb, 0, 'The default steps 0.02 below the data minimum. That is a statement about where the lab stopped measuring, not about where the rock stops draining, which is why the override exists and why evidence such as log-derived connate water is the right thing to feed it.'),
  ('scal', 'intermediate', 'module', 'm04-fitting-and-averaging', 7, 'The Ekene lab tables run down to Sw of 0.30. Where does the Swirr default land, and what is the design truth?', '["Default 0.30, truth 0.28", "Default 0.25, truth 0.25", "Default 0.02, truth 0.25", "Default 0.28, truth 0.25"]'::jsonb, 3, 'The default is the data floor of 0.30 minus 0.02, giving 0.28, while the curves were generated with 0.25. The data alone cannot see below their own floor, so the heuristic quietly promotes an apparatus limit into a physical parameter.'),
  ('scal', 'intermediate', 'module', 'm04-fitting-and-averaging', 8, 'What is the tell that a supplied or defaulted Swirr sits too high for genuinely power-law data?', '["The Levenberg-Marquardt iteration fails to converge within its budget of sixty iterations", "The fitted a comes back negative", "The log-space r squared drops and the residuals bow", "The engine raises an exception naming Swirr"]'::jsonb, 2, 'A wrong Swirr warps the Sw* axis unevenly, so points that truly follow a power law no longer sit on a straight line in log coordinates. The fit still converges comfortably inside its iteration budget and a stays positive; the damage appears in the fit quality and in the bowed residual pattern, one sign at the ends and the other in the middle.'),
  ('scal', 'intermediate', 'module', 'm04-fitting-and-averaging', 9, 'Before averaging several plugs, why must each sample first be re-keyed to the normalized saturation Sw*?', '["The same Sw can mean different states in plugs with different Swirr", "The geometric mean is only defined when every value lies strictly between 0 and 1", "Interpolation in the logarithm of J requires a normalized axis", "The overlap grid cannot be computed on raw saturations"]'::jsonb, 0, 'A saturation of 0.35 can be deep inside one plug''s transition zone and at the very edge of another''s, so averaging at fixed Sw would mix unlike physical states. Normalization aligns the physics first. The mean, the interpolation and the grid machinery would all run on any positive axis; they are not the reason.'),
  ('scal', 'intermediate', 'module', 'm04-fitting-and-averaging', 10, 'At each grid point, how does averageJCurves combine the values from the different samples?', '["Arithmetic mean with outliers dropped", "Geometric mean, with min and max kept as a band", "Median, with quartiles kept as the spread", "A mean weighted by each plug''s permeability and porosity through the root k over phi factor"]'::jsonb, 1, 'J is a positive, ratio-like quantity, so the engine averages the logarithms, which is the geometric mean, and records the min and max alongside as the disagreement band. Nothing is dropped, and nothing is weighted by rock properties: the J transform already removed the rock scaling.'),
  ('scal', 'intermediate', 'module', 'm04-fitting-and-averaging', 11, 'Three plugs carry normalized J data over 0.08 to 1.0, 0.12 to 1.0, and 0.06 to 0.96. Over what range does the engine average?', '["0.06 to 1.0", "0.08 to 0.96", "0.12 to 0.96", "0.06 to 0.96"]'::jsonb, 2, 'The grid runs from the largest of the sample minima to the smallest of the maxima, here 0.12 to 0.96. Outside that overlap at least one sample would contribute a clamped endpoint rather than data, and the engine averages only where every sample genuinely speaks.'),
  ('scal', 'intermediate', 'module', 'm04-fitting-and-averaging', 12, 'How should the power-law fit that averageJCurves returns with its mean grid be read?', '["As the definitive reservoir curve, superseding the single-plug fits", "As a diagnostic only, never to be used downstream", "As the exact recovery of the design curve", "A candidate spec, checked against the direct fit of raw points"]'::jsonb, 3, 'The refit is a fit of an average of interpolations, three modelling layers away from the lab data, so it is offered as a candidate. The standing check is to compare it with a direct fit of a single plug''s raw points; when the plugs genuinely share one curve, the two agree closely.'),
  ('scal', 'intermediate', 'module', 'm04-fitting-and-averaging', 13, 'Why is averaging the plugs'' capillary pressure curves directly, saturation by saturation, the wrong move?', '["Pc curves cannot be interpolated between their measured points", "Each plug''s Pc is scaled by its own rock, so the average is a curve that is correct for no rock at all", "Pc changes sign over part of the drainage branch", "The plugs were measured with different fluid systems, so their Pc values carry different units"]'::jsonb, 1, 'A high-permeability plug''s low Pc and a tight plug''s high Pc are both correct for their own rock; blending them mixes rock scaling into the result. The J transform removes that scaling first, which is the entire reason averaging happens in J space. The fluid systems do differ, but every Pc is still a pressure in the same units.'),
  ('scal', 'intermediate', 'module', 'm04-fitting-and-averaging', 14, 'The Figure 4-18 golden is stored as nine figure reads at a tolerance of 0.05 in J. What claim can the fit legitimately make against it?', '["That the fitted curve passes within the read tolerance of every read", "That a equals 0.3922841458642378 as a physical property of the 1941 sands", "That the original plate carried four decimal places of precision", "That the read tolerance tightens once the fit has converged"]'::jsonb, 0, 'The claim stops where the source stops. A curve on a printed grid can honestly be read to about 0.05 in J, and the fit''s largest miss is 0.027530745172516413, inside that with margin. The full-precision parameters are recorded so the fit is reproducible, not because the plate supports those digits.'),
  ('scal', 'intermediate', 'module', 'm04-fitting-and-averaging', 15, 'The Ekene design carries b of 1.0 while the Figure 4-18 sands fit near b of 0.18. What does this contrast express?', '["The Ekene fit failed to resolve the plateau at the wet end of the curve", "The Leverett collapse does not hold for consolidated rocks", "Shape belongs to the rock family; the collapse is about scaling", "The figure reads were taken at too coarse a tolerance to fix b"]'::jsonb, 2, 'The collapse claim says one rock family reduces to one dimensionless curve; it says nothing about which shape that curve has. Well-sorted unconsolidated sand drains over a narrow pressure interval and gives a plateau-like low exponent, while a broader pore-size distribution steepens the curve. Exponents summarise sorting, and comparing them across rocks is real geological information.'),
  ('scal', 'intermediate', 'module', 'm05-saturation-height', 1, 'The engine''s heightFromPc converts a capillary pressure to a height above the free water level. Which expression does it evaluate?', '["h = Pc x 0.4335 x (gammaW - gammaHc), with h in metres", "h = Pc / (0.4335 x (gammaW - gammaHc)), with h in feet", "h = Pc / (0.3048 x (gammaW + gammaHc)), with h in feet", "h = (gammaW - gammaHc) / (0.4335 x Pc), with h in metres"]'::jsonb, 1, 'The phase pressure gap grows at 0.4335 psi per foot per unit of specific gravity contrast, so height is capillary pressure divided by 0.4335 times the contrast, and the engine returns it in feet. Multiplying instead of dividing, mixing in the metre conversion constant, or adding the gravities all produce dimensionally wrong chains.'),
  ('scal', 'intermediate', 'module', 'm05-saturation-height', 2, 'Using the Ekene fluid pair, gammaW 1.03 and gammaO 0.8654434250764526, what is the working capillary pressure gradient of the column?', '["0.4335 psi/ft, the fresh water constant itself", "0.16455657492354747 psi/ft", "0.07133527522935783 psi/ft", "0.2340396168942186 psi/ft"]'::jsonb, 2, 'The gradient is 0.4335 multiplied by the density contrast of 0.16455657492354747, giving 0.07133527522935783 psi per foot. The contrast alone carries no pressure unit, the bare 0.4335 applies only to a fresh water column against vacuum oil of zero density, and 0.2340396168942186 is this same gradient expressed per metre rather than per foot.'),
  ('scal', 'intermediate', 'module', 'm05-saturation-height', 3, 'The Ekene oil specific gravity used for saturation-height work is 0.8654434250764526. Where does that number come from?', '["It is computed as 141.5/(131.5 + API) with the field''s locked API of 32", "It was measured on the EK3-P plug during the mercury injection program", "It is the geometric mean of the brine gravity 1.03 and the design Swirr 0.25", "It is fitted alongside a and b when fitJPowerLaw runs on the collapsed J data"]'::jsonb, 0, 'API gravity converts to specific gravity through 141.5/(131.5 + API), and the fixture''s oil was locked at API 32 by the PVT work, giving 0.8654434250764526 exactly. Mercury injection measures capillary pressure rather than oil density, and neither the J-function fit nor any average of unrelated design constants produces a fluid gravity.'),
  ('scal', 'intermediate', 'module', 'm05-saturation-height', 4, 'What defines the free water level in a saturation-height model?', '["The shallowest depth at which a resistivity log reads fully water saturated rock", "The depth at which the drainage curve reaches the irreducible saturation", "The depth of the deepest well penetration that flowed water on test", "The depth at which the oil and water phase pressures are equal, so Pc is zero"]'::jsonb, 3, 'The free water level is a pressure datum: where the two phase pressure lines cross and capillary pressure vanishes. The shallowest fully wet rock defines the contact instead, which sits one entry height above the datum. Irreducible saturation is approached at great height, and well observations sample the column without defining its datum.'),
  ('scal', 'intermediate', 'module', 'm05-saturation-height', 5, 'The Ekene design places Sw = 1.0 exactly at the mapped 1560 m contact. At what depth does the free water level sit?', '["1570.31162356877775 m, one engine height unit below the contact", "1560 m, because the free water level and the mapped contact coincide by definition", "1556.8570171362364 m", "1563.1429828637636 m"]'::jsonb, 3, 'The free water level lies one entry height, 3.142982863763458 m, BELOW the contact, at 1563.1429828637636 m TVD. Subtracting the entry height instead puts it above the contact, adding the raw 10.31162356877775 as if feet were metres lands at 1570.3 m, and equating the two levels ignores the entry pressure entirely.'),
  ('scal', 'intermediate', 'module', 'm05-saturation-height', 6, 'Between the free water level and the mapped contact of a drainage system, what state is the rock in?', '["Fully water saturated even though capillary pressure is above zero", "At irreducible water saturation, since drainage there is complete", "Oil bearing, with saturation partway down the transition zone", "Fully water saturated because capillary pressure is exactly zero throughout the band"]'::jsonb, 0, 'In the entry band the capillary pressure is positive but still below the entry pressure, so the largest pore throats have not yet admitted oil and the rock stays at Sw = 1. Capillary pressure is zero only at the free water level itself, and both oil-bearing states belong to depths above the contact.'),
  ('scal', 'intermediate', 'module', 'm05-saturation-height', 7, 'Expressed in metres, the Ekene entry height, the thickness of the band between the free water level and the contact, is which of these?', '["10.31162356877775 m", "3.142982863763458 m", "0.7355825053402938 m", "6.285965727526915 m"]'::jsonb, 1, 'The entry pressure of 0.7355825053402938 psi converts to 10.31162356877775 feet of column, which is 3.142982863763458 metres. Quoting 10.31 in metres repeats the feet figure in the wrong unit, 0.7355825053402938 is the pressure itself rather than a height, and 6.285965727526915 m is where the profile first reaches Sw 0.50 above the contact.'),
  ('scal', 'intermediate', 'module', 'm05-saturation-height', 8, 'On the designed Ekene curve, how far above the CONTACT does the column first dry to Sw = 0.50?', '["2.09532190917564 m", "8.643202875349512 m", "6.285965727526915 m", "12.571931455053829 m"]'::jsonb, 2, 'The halfway saturation is reached 6.285965727526915 m above the contact. The nearer figure of 2.09532190917564 m belongs to Sw 0.70, while 8.643202875349512 m and 12.571931455053829 m are the rungs for 0.45 and 0.40; the ladder spreads out with height because the curve flattens toward its asymptote.'),
  ('scal', 'intermediate', 'module', 'm05-saturation-height', 9, 'The Ekene transition zone drops from Sw 1.0 to 0.5 within about six metres, yet needs almost six more metres just to go from 0.40 to 0.36. What explains that shape?', '["Permeability degrades upward through the sand, so the upper column drains more slowly than the base despite the same fluid pair", "The mercury lab system used on EK3-P exaggerates pressures high in the column", "The engine''s height grid is coarser near the crest than near the contact", "Big throats drain at low Pc near entry; near the asymptote each further point of drying costs ever more height"]'::jsonb, 3, 'The profile is the drainage curve read sideways. Just above entry pressure, small pressure increments empty the big throats quickly; near the irreducible asymptote, each further point of drying requires a large pressure and therefore height increment. The fixture''s rock properties are uniform, the lab system cancels out inside J, and the engine grid does not shape the physics.'),
  ('scal', 'intermediate', 'module', 'm05-saturation-height', 10, 'Two columns share the same dimensionless drainage curve. Column A holds light oil in good sand; column B holds heavier oil in tighter rock. What happens to B''s transition zone compared with A''s?', '["It stretches vertically: a smaller density contrast and a larger psi-per-J factor both demand more height per saturation change", "It compresses vertically, because tighter rock always drains over a shorter interval", "It keeps the same thickness, since the dimensionless curve fixes the geometry in depth", "It stretches only if the porosity also falls, since permeability does not enter the scaling"]'::jsonb, 0, 'Height per unit J scales with the rock factor, and pressure per unit height scales with the density contrast, so tight rock and a weak contrast both multiply the thickness of the same dimensionless curve. The curve fixes shape, never depth extent, and permeability enters the scaling through the square root of k over phi.'),
  ('scal', 'intermediate', 'module', 'm05-saturation-height', 11, 'What saturation does the designed Ekene curve give at the crest of the structure?', '["0.25, since the highest point of a column always drains to the irreducible value", "0.35062979402484734", "0.36, the last rung of the transition ladder before the crest", "0.48353582519437843"]'::jsonb, 1, 'At 76.85316015526888 ft above the free water level the chain gives J of 1.8632652666833722 and a saturation of 0.35062979402484734, which is why the booking''s flat 0.35 matches the crest to the third decimal. The irreducible 0.25 is an asymptote never reached at finite height, 0.36 is passed two metres lower, and 0.48353582519437843 is the metres figure for the 0.90 rung, not a saturation.'),
  ('scal', 'intermediate', 'module', 'm05-saturation-height', 12, 'The NG5 volumetric booking painted Sw = 0.35 across the entire Ekene oil leg. Relative to the capillary model, what does that flat assignment do to the booked oil?', '["It understates oil, because the flat model ignores oil held in the transition zone below the contact", "It matches the capillary model, since 0.35 was chosen as the column-wide average", "It overstates oil, because 0.35 is the driest saturation the column reaches and only the crest attains it", "Its bias cannot be signed without knowing the areal distribution of the 169 cells"]'::jsonb, 2, 'The capillary profile shows 0.35 is achieved only at the single highest point, with every depth below it wetter, so a flat 0.35 assigns crest dryness to rock that cannot support it and the correction must run downward. There is no bookable oil below the contact to recover, and the sign of the bias follows from the profile alone, cell layout or averaging claims notwithstanding.'),
  ('scal', 'intermediate', 'module', 'm05-saturation-height', 13, 'An engineer computes the crest capillary pressure by multiplying the crest height in METRES, 23.424843215325957, by the gradient 0.07133527522935783 psi/ft, getting 1.6710176379698325 psi. What went wrong?', '["Nothing; the engine confirms that value for the crest", "The gradient should first be divided by the entry pressure before multiplying", "The height should be measured from the contact, not the free water level, before multiplying", "Metres went into a per-foot gradient, understating the true 5.482341331922022 psi by the factor 3.2808"]'::jsonb, 3, 'A psi-per-foot gradient demands a height in feet, 76.85316015526888 here, and using metres silently divides the answer by the conversion factor 1/0.3048. The correct crest pressure is 5.482341331922022 psi. Measuring from the contact would be a second, different error, and no legitimate step divides a gradient by an entry pressure.'),
  ('scal', 'intermediate', 'module', 'm05-saturation-height', 14, 'To run the Ekene saturation-height chain entirely in metric heights, which single change is sufficient?', '["Replace 0.4335 with 0.3048 in the height formula", "Convert the gradient once to 0.2340396168942186 psi per metre and use metre heights throughout", "Multiply every computed saturation by 0.3048 at the end of the chain", "Convert each pressure to kilopascals before dividing by the per-foot gradient"]'::jsonb, 1, 'Dividing the per-foot gradient by 0.3048 gives 0.2340396168942186 psi per metre, after which metre heights flow through the same arithmetic. The 0.4335 constant is a physical water gradient, not a unit converter, saturations are dimensionless and never unit-scaled, and switching pressure units while keeping a per-foot gradient only compounds the mismatch.'),
  ('scal', 'intermediate', 'module', 'm05-saturation-height', 15, 'What capillary pressure does the designed model assign to the very top of the Ekene structure?', '["0.7355825053402938 psi", "11.03373758010441 psi", "5.482341331922022 psi", "1.6710176379698325 psi"]'::jsonb, 2, 'The crest stands 76.85316015526888 ft above the free water level, and multiplying by the column gradient gives 5.482341331922022 psi. The entry pressure 0.7355825053402938 psi belongs at the contact, 11.03373758010441 psi is the curve''s value down at Sw 0.30 which the short Ekene column never reaches, and 1.6710176379698325 psi is the metre-for-foot slip from the unit lesson.'),
  ('scal', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'The Professional capstone grades the reservoir capillary pressure of Ahmed Example 4-7 at Sw 0.2 as 1.5534071373580902 psi. Which chain produces that value?', '["Rescaling the full-precision engine J column through the factor 9.191758209219469, which lands at 1.5570739117545667 psi", "Rescaling the book''s printed three-decimal J column, the chain the book itself runs", "Fitting a power law to the lab J data and evaluating it at Sw 0.2", "Averaging the printed-chain and full-precision values"]'::jsonb, 1, 'The published example rescales its own rounded J column, so the graded value follows the printed chain. The full-precision chain differs by more than the grading tolerance, which is exactly why the capstone names the chain. Averaging two chains or inserting a power-law fit are chains the book never ran.'),
  ('scal', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'The engine reports the Ekene entry height as 10.31162356877775 in its native unit. What should you submit for the capstone''s entry height field?', '["3.142982863763458 m, the feet output carried through the exact factor 0.3048", "10.31162356877775 m, the engine''s native output read directly", "33.83078598680364 m, dividing by 0.3048 instead of multiplying", "0.7355825053402938 m, submitting the entry pressure in place of the entry height"]'::jsonb, 0, 'Heights come out of the engine in feet because the height conversion uses the field-unit gradient. The capstone''s Ekene fields are metres, so the feet value is multiplied by 0.3048 exactly. Dividing instead of multiplying is the classic wrong-way conversion, and the last option confuses a pressure with the height it produces.'),
  ('scal', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'The Ekene free water level is graded at 1563.1429828637636 m TVD while the mapped contact is 1560 m. Why is the free water level the deeper of the two?', '["The mapping ladder smoothed the contact upward by the 3.142982863763458 m entry height", "The free water level is defined at the base of the sand, which lies deeper than the mapped top", "The oil column''s buoyancy presses the water leg downward by exactly the entry height", "The entry pressure keeps rock fully water-saturated for the entry height above the zero of capillary pressure"]'::jsonb, 3, 'Capillary pressure is zero at the free water level, but oil cannot enter the rock until the entry pressure is overcome, so a water leg the entry height thick sits above that zero. The mapped contact is the top of that water leg. Neither mapping error nor buoyancy loading has anything to do with the separation.'),
  ('scal', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'The saturation-height model puts Sw at the Ekene crest at 0.35062979402484734. What does this say about the geoscience booking that used a flat Sw of 0.35 everywhere?', '["The booking is invalidated and the volumetric oil in place must be restated", "The two agree to within rounding, so the flat value is exact at every depth", "The flat value holds at the crest alone, and every cell below it is wetter", "The 0.35 is a lab connate value with no meaning away from the plugs"]'::jsonb, 2, 'The design puts the crest right where the drainage curve reaches the connate plateau, so 0.35 is true at the very top of the column only. Below the crest the transition zone raises water saturation toward 1.0 at the contact. The flat booking is a crest-value approximation applied everywhere, which is a scoping judgment rather than an error demanding restatement.'),
  ('scal', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'Your new field''s J data refuses to follow a power law: the residuals curve systematically. Within this course''s engine, what is the correct next step?', '["Carry the measured J rows as a tabulated spec and interpolate", "Switch to a Thomeer hyperbola for the plateau shape", "Keep the power law and report the widened confidence intervals", "Fit separate power laws above and below the plateau"]'::jsonb, 0, 'The engine is locked to one parametric form, and its designed alternative for data that will not follow it is the tabulated J spec. Thomeer is explicitly outside the lock, so no such fallback exists. Forcing a bad model or stitching piecewise fits invents structure the tool was built to refuse.'),
  ('scal', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'A saturation-height function built from drainage capillary pressure data describes which of the following?', '["The saturations a waterflood leaves behind each producer after breakthrough", "The residual oil saturation the displacement half of the course grades at field abandonment", "The initial fluid distribution the reservoir charged to before production", "The saturation path the front follows between wells"]'::jsonb, 2, 'Drainage is the history that charged the reservoir, the non-wetting phase displacing water over geological time, so a model built on that branch answers where the fluids started. Flood-out saturations, residuals, and front paths belong to imbibition and to the displacement half, which uses different curves.'),
  ('scal', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'The Ekene kr set uses a connate water saturation of 0.35 while the capillary design uses an irreducible saturation of 0.25. How can both be correct?', '["One of the two is a preserved typographical error the fixture keeps for teaching purposes", "Different experiments: the crest zone drains to the kr connate, while the capillary value is the drainage asymptote", "The kr value includes clay-bound water in its count while the capillary measurement excludes it from the pore volume", "The capillary value applies only below the 1560 m contact, where oil never entered the rock"]'::jsonb, 1, 'The drainage curve approaches its asymptote at 0.25, but the Ekene column is only tall enough to drain the crest to about 0.35, and the rel-perm set describes flow in that drained zone. The two conventions answer different questions, and the fixture keeps them deliberately distinct so they cannot be confused.'),
  ('scal', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'The factor 0.0967993827459659 per psi in Ahmed Example 4-7 converts lab capillary pressure into J. Whose properties does it contain?', '["The reservoir rock''s, 120 md and porosity 0.19", "A geometric average of the lab core and reservoir rock, since both appear somewhere in the chain", "Only the fluid pair''s, since the dimensionless form removes the rock", "The lab core''s, 80 md and porosity 0.16, with the lab fluid pair"]'::jsonb, 3, 'J scaling always uses the rock and fluids of the measurement being converted, so the lab factor carries the lab core''s permeability and porosity along with the lab system''s interfacial tension and contact angle. The reservoir''s properties enter later, in the separate factor that carries J back out to reservoir capillary pressure.'),
  ('scal', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'An analyst builds the Ahmed 4-7 lab J column but mistakenly uses the reservoir rock''s k and phi in the factor. What happens to the J values?', '["The whole column rides off the true curve by one constant multiple set by the two rocks'' k over phi ratio", "Nothing changes, because the same factor cancels exactly when the curve is rescaled back to the reservoir rock", "Only the values near the asymptote shift, where the error compounds against the low-saturation plateau", "The column scatters randomly, because the error meets each measured pressure differently"]'::jsonb, 0, 'The rock enters J through the square root of k over phi, a single multiplicative constant, so a wrong rock moves the whole curve by one fixed multiple. This is the same diagnostic signature module 2 taught for a mis-typed permeability: the curve rides cleanly off the collapse rather than scattering.'),
  ('scal', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'What exactly does the Leverett J-function remove from a measured capillary pressure curve?', '["The saturation dependence, leaving one characteristic entry pressure per rock family", "The reservoir wettability, replacing it with the laboratory system''s contact angle convention", "Measurement scatter, through built-in geometric averaging", "The rock scale and the fluid pair, leaving the saturation dependence"]'::jsonb, 3, 'J divides out the fluid pair through sigma cos theta and multiplies in the square root of k over phi, stripping both the lab system and the plug''s rock scale. What survives is the dimensionless shape against saturation, which is why plugs measured in different fluids on different rocks can share one curve.'),
  ('scal', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'Which statement about the SCAL engine''s deliberate limits is true?', '["It falls back to Thomeer parameters whenever the power-law fit fails to converge on a sample", "Its only parametric capillary model is the power law, with tables as the designed alternative", "It carries drainage and imbibition branches and switches between them on demand", "It offers a three-phase relative permeability model evaluated at connate water saturation"]'::jsonb, 1, 'The owner lock keeps the engine thin: one parametric form, one branch, two phases, contact angle taken as given. Data that will not power-law is carried as a table rather than pushed into a richer model. Each other option names something the lock explicitly excludes.'),
  ('scal', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'Why does the capstone walkthrough insist on submitting values at full precision rather than rounded?', '["The grader rejects fields carrying fewer than fifteen significant figures", "Rounded values are considered dishonest in engineering reports", "Full precision costs nothing to copy and stays inside every tolerance", "Full-precision entries prove the panel produced the number rather than a hand calculator"]'::jsonb, 2, 'The tolerances are set tightly enough to distinguish right chains from wrong ones, and the Nameless Field example showed a rounding chain moving an answer by more than a grading tolerance. Copying the engine''s full output sidesteps the risk entirely. Rounding is fine in prose for humans, but a grader is not asking for readability.'),
  ('scal', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'A mercury-injection capillary pressure table reads roughly six times higher than an air-brine table on the same rock family, yet both produce the same J curve. Why?', '["Each system''s sigma cos theta divides its own pressures on the way into J", "Mercury data is first corrected to brine equivalents by the 0.0967993827459659 factor before J is computed", "The two systems sample different pore networks that happen to compensate", "J is normalized by its own maximum for each sample"]'::jsonb, 0, 'Each lab system''s interfacial tension and contact angle enter J in the denominator, so a fluid pair that raises every measured pressure also raises the divisor by the same factor. No brine-equivalent correction is applied, and that factor belongs to the Ahmed lab core rather than to any mercury conversion; no per-sample normalization exists.'),
  ('scal', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'Module 4 taught that the power-law refit of an averaged J curve is a candidate rather than an answer. What is the check it must pass?', '["Its exponent must land between the steepest and the flattest single-sample exponents in the set", "It must reproduce the tightest plug''s entry pressure to within the figure-read tolerance of 0.05 J", "Comparison against the raw samples'' direct fits, with the refit''s own fit quality as the tell", "A leave-one-out re-run over the samples, dropping each plug from the average in turn"]'::jsonb, 2, 'The averaging machinery resamples each curve before refitting, and the shared irreducible saturation choice can distort the normalized axis, so the module named two tells: the direct fits on raw points and the refit''s own log-space fit quality. The other options describe checks the engine does not perform.'),
  ('scal', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'A reviewer receives your saturation-height study. According to this tier, which set of declarations belongs in the same paragraph as the headline numbers?', '["The software version, the run date, the random seed, and the analyst''s initials for the audit trail", "The measured branch, the samples with their shared Swirr, fitted versus tabulated, and the assumed fluid properties", "The complete J table at every saturation, printed at machine precision for reproducibility", "The permeability map of the field and the well list the fluid contacts were picked from"]'::jsonb, 1, 'Those four items are the places where two competent analysts can legitimately diverge, so naming them is what makes the work checkable rather than merely assertable. Administrative metadata and bulk tables belong in appendices, and the mapping inputs are the geoscience workflow''s declarations rather than this study''s.'),
  ('scal', 'intermediate', 'final', null, 1, 'In a water-wet rock during drainage, capillary pressure is defined as which pressure difference?', '["The wetting-phase pressure minus the non-wetting-phase pressure", "The overburden pressure minus the pore pressure at the same depth", "The non-wetting-phase pressure minus the wetting-phase pressure", "The injection pressure minus the hydrostatic pressure at the measurement point"]'::jsonb, 2, 'Capillary pressure is the excess pressure the non-wetting phase carries over the wetting phase, Pc = pnw minus pw. In drainage the non-wetting phase is invading, so Pc is positive and grows as it is forced into smaller throats.'),
  ('scal', 'intermediate', 'final', null, 2, 'Three plugs from the same Ekene sand family were measured with air-brine, mercury-air, and oil-brine systems. Why does the mercury-air table read several times higher than the others at the same saturation?', '["The sigma cos theta of the mercury-air pair is much larger, and that product sets the pressure scale", "Mercury reacts chemically with the clay fraction of the rock and progressively plugs the finest pore throats during injection", "The mercury plug has a much lower permeability than the other two plugs", "Mercury laboratories report their tables in kilopascals while the air-brine and oil-brine systems report psi"]'::jsonb, 0, 'Pc scales with sigma cos theta: the mercury-air pair carries 480 dyn/cm at 40 degrees against 72 for air-brine and 48 for oil-brine. The rock contributes the same sqrt(k/phi) either way, which is why all three tables collapse to one J curve.'),
  ('scal', 'intermediate', 'final', null, 3, 'At Sw 0.30, plug EK3-P (mercury-air) reads which capillary pressure?', '["29.190762994489138 psi", "180.18302550343515 psi", "29.55586916053684 psi", "11.03373758010441 psi"]'::jsonb, 1, 'The mercury-air fluid pair sets a far higher pressure scale. 29.190762994489138 psi is EK1-P on air-brine, 29.55586916053684 psi is EK5-P on oil-brine, and 11.03373758010441 psi is the reservoir oil-brine value at the same saturation.'),
  ('scal', 'intermediate', 'final', null, 4, 'validatePcTable rejects exactly one of these drainage tables. Which one, and for which rule?', '["Five rows with distinct Sw values, all Pc positive and falling as Sw rises: rejected because a drainage table needs at least eight rows", "A table whose highest saturation row sits exactly at Sw 1.0: rejected because Sw may never reach 1", "A table with Pc equal to zero in its wettest row: rejected because Pc must be strictly positive", "A table where Pc rises from Sw 0.6 to Sw 0.8: a drainage curve must be non-increasing in Sw"]'::jsonb, 3, 'The rules are: at least 3 rows, Sw within (0, 1], Pc non-negative, no duplicate Sw, and Pc non-increasing in Sw. Five valid rows pass, Sw of exactly 1 is allowed, and a zero Pc is allowed; only the rising segment breaks a rule.'),
  ('scal', 'intermediate', 'final', null, 5, 'On the Ekene reservoir rock the capillary pressure at Sw = 1 is 0.7355825053402938 psi rather than zero. What is this value called and what does it mean physically?', '["The plateau pressure: the level at which the curve flattens across the middle saturations", "The entry pressure: oil cannot invade even the largest pore throats until the capillary pressure reaches this finite value", "The asymptote pressure: the limit the drainage curve approaches as Sw falls toward the irreducible saturation", "The residual pressure: the Pc left behind after imbibition returns the rock to residual oil"]'::jsonb, 1, 'A finite Pc at full water saturation is the entry (displacement) pressure of the largest throats. Below it the rock stays fully water saturated, which is exactly what separates the free water level from the mapped contact.'),
  ('scal', 'intermediate', 'final', null, 6, 'Which saturation change defines a drainage measurement?', '["The non-wetting phase displaces the wetting phase out of the pore space, so the water saturation decreases", "The wetting phase displaces the non-wetting phase, so Sw increases", "Both phases flow at fixed saturation while the confining pressure is cycled", "The core is flushed with brine until the water saturation returns to one"]'::jsonb, 0, 'Drainage means the wetting phase is being drained: the non-wetting phase invades and Sw falls. The reverse direction is imbibition, and the two branches differ, which is why the direction of a lab curve must always be stated.'),
  ('scal', 'intermediate', 'final', null, 7, 'Why does capillary pressure keep rising as Sw falls along a drainage curve?', '["Because the wetting film thickens as the rock dries out", "Because permeability falls with saturation, and Pc scales inversely with permeability", "Because the non-wetting phase must enter ever smaller pore throats, and smaller radii demand higher curvature pressure", "Because the interfacial tension itself increases sharply at low water saturation as the brine films thin toward molecular thickness"]'::jsonb, 2, 'Invasion proceeds from the largest throats to the smallest. The pressure needed to push a curved interface through a throat rises as the radius shrinks, so the drainage curve climbs toward an asymptote near the irreducible saturation.'),
  ('scal', 'intermediate', 'final', null, 8, 'In the Leverett J-function, the rock enters through which combination?', '["The product of permeability and porosity", "The square root of k over phi", "The square root of phi over k", "The logarithm of the ratio k over phi"]'::jsonb, 1, 'J = C times (Pc over sigma cos theta) times sqrt(k/phi). The square root of k over phi is a characteristic pore-throat length scale, which is what lets rocks of different quality share one dimensionless curve.'),
  ('scal', 'intermediate', 'final', null, 9, 'The engine''s LEVERETT_C is 0.21645, while deriving the constant from exact CGS conversions gives 0.21665. Why is the discrepancy harmless in practice?', '["The two constants agree to five significant figures, so the difference can never reach a measured pressure", "The engine averages the two constants internally before any scaling is applied", "The derived constant is only valid for mercury injection systems measured at laboratory temperature and pressure rather than reservoir conditions", "Every Pc to J conversion and its inverse run through the same constant, so the round trip is exact whichever one is adopted"]'::jsonb, 3, 'The published field-unit constant is adopted verbatim and the relative difference is 0.0009240009240009504, about 0.09 percent. What matters downstream is that Pc to J and J back to Pc use one constant, making the round trip exact.'),
  ('scal', 'intermediate', 'final', null, 10, 'The three Ekene plugs collapse to one J curve with a maximum spread of 4.440892098500626e-16. What does that number tell you?', '["The spread sits at machine epsilon: the collapse is exact in double precision", "The collapse fails by half a percent, which is inside ordinary lab tolerance", "The spread equals the read tolerance of the 1941 correlation figure", "The J values differ by roughly 4.4 percent at the tightest grid point"]'::jsonb, 0, 'A spread of order 1e-16 is floating-point epsilon: the three tables reduce to the same curve exactly, because the fixture generated each lab table from one designed J curve and the transform inverts it without error.'),
  ('scal', 'intermediate', 'final', null, 11, 'An analyst types a plug''s permeability as four times its true value before computing J. What does the collapse plot show?', '["The plug''s J curve falls exactly four times below the rest of the cloud", "The plug''s J curve is unchanged because permeability cancels out of J", "The plug''s J curve rides exactly twice as high as the others", "The plug''s J curve crosses the others near the middle of the saturation range"]'::jsonb, 2, 'J carries sqrt(k/phi), so a 4x error in k multiplies the whole curve by sqrt(4) = 2. The shape is preserved and the shift is uniform, which is exactly the signature that separates a scaling typo from a genuinely different rock.'),
  ('scal', 'intermediate', 'final', null, 12, 'At Sw 0.30 every Ekene plug carries the same J value. What is it?', '["2.942330021361175", "3.75", "0.25", "11.03373758010441"]'::jsonb, 1, 'J(0.30) = 0.25 times ((0.30 minus 0.25) over 0.75) to the power minus 1 = 0.25 times 15 = 3.75. The value 2.942330021361175 is the reservoir psi-per-J factor, 0.25 is the parameter a, and 11.03373758010441 psi is the reservoir Pc there.'),
  ('scal', 'intermediate', 'final', null, 13, 'Between the plugs'' lab tables and the single J curve, what information is removed by the J transform?', '["The saturation axis of the measurement, which the transform replaces with a normalized coordinate", "The drainage direction of the measurement", "The shape of the curve, which the transform flattens onto a straight line in log space", "The rock scaling carried in sqrt(k/phi) together with the fluid scaling carried in sigma cos theta"]'::jsonb, 3, 'The transform divides out the fluid pair through sigma cos theta and the rock quality through sqrt(k/phi), leaving a dimensionless curve. Saturation, direction, and shape all survive; only the scalings are removed.'),
  ('scal', 'intermediate', 'final', null, 14, 'What is the relative difference between the published constant 0.21645 and the CGS-derived value 0.21665?', '["0.0009240009240009504, about 0.09 percent", "0.0092400092400095, about 0.9 percent", "0.021645, about 2 percent", "9.240009240009504e-07, about 0.0001 percent"]'::jsonb, 0, '(0.21665 minus 0.21645) over 0.21645 = 0.0009240009240009504. It is a 0.09 percent difference, small, and made irrelevant in practice by running both directions of the conversion through the same adopted constant.'),
  ('scal', 'intermediate', 'final', null, 15, 'For the Nameless Field lab core (k 80 md, phi 0.16, sigma 50 dyn/cm, theta 0), the factor that turns lab Pc into J is which value?', '["9.191758209219469 per psi", "0.21645 per psi", "0.0967993827459659 per psi", "0.4335 per psi"]'::jsonb, 2, 'The factor is C sqrt(k/phi) over sigma cos theta = 0.0967993827459659, which the book prints as 0.096799. The value 9.191758209219469 is the reservoir psi-per-J factor, 0.21645 is the Leverett constant itself, and 0.4335 is the fresh-water gradient.'),
  ('scal', 'intermediate', 'final', null, 16, 'The engine computes J at Sw 0.2 for the Nameless Field core as 0.16939891980544033, while the book prints 0.169. How should you treat the two numbers?', '["As the same quantity at different rounding: the print is the engine value rounded to three decimals", "As a disagreement which means the engine mis-reads the published table and its golden fixture needs to be re-armed", "As two different definitions of J that cannot be compared directly", "As evidence that the book used a different value of the Leverett constant when it computed its printed J column"]'::jsonb, 0, 'The book rounds its J column to three decimals for print. Both statements describe one measurement; the working discipline is to know which version a downstream number was built from, because the rounding propagates.'),
  ('scal', 'intermediate', 'final', null, 17, 'Rescaling J to the Nameless Field reservoir rock (k 120 md, phi 0.19) uses which psi-per-J factor?', '["0.0967993827459659", "2.942330021361175", "0.096799", "9.191758209219469"]'::jsonb, 3, 'The reservoir factor is sigma cos theta over (C sqrt(k/phi)) = 9.191758209219469 psi per unit J, which the book prints as 9.192. The first and third options are the lab J-per-psi factor at two precisions, and 2.942330021361175 is the Ekene reservoir factor.'),
  ('scal', 'intermediate', 'final', null, 18, 'Following the book''s own chain, which rescales the PRINTED three-decimal J column, the reservoir Pc at Sw 0.2 is which value?', '["1.5570739117545667 psi", "1.5534071373580902 psi", "1.75 psi", "0.9375593373403855 psi"]'::jsonb, 1, 'The printed J of 0.169 times 9.191758209219469 gives 1.5534071373580902 psi, matching the book''s 1.553. The value 1.5570739117545667 comes from the full-precision J column, 1.75 psi is the LAB Pc at that saturation, and 0.9375593373403855 psi belongs to Sw 0.4.'),
  ('scal', 'intermediate', 'final', null, 19, 'Rescaling the FULL-precision J column instead of the printed one gives which reservoir Pc at Sw 0.2?', '["1.5534071373580902 psi", "1.553 psi", "1.5570739117545667 psi", "1.6939891980544033 psi"]'::jsonb, 2, 'The unrounded J of 0.16939891980544033 rescales to 1.5570739117545667 psi. The first two options are the printed chain at two precisions, and the last is a decimal shift of the J value itself, not a pressure.'),
  ('scal', 'intermediate', 'final', null, 20, 'The printed-chain and full-chain reservoir Pc values at Sw 0.2 differ by about 0.0037 psi. Where does the difference come from?', '["The book rounded its printed J column to three decimals, and the rescaling multiplies that rounding straight through the chain", "The engine uses the derived constant 0.21665 for the reservoir step only", "The reservoir porosity was typed differently in the two chains, 0.19 in one computation and 0.16 in the other one", "Linear interpolation between the five printed table rows introduces the gap when the engine resamples the curve"]'::jsonb, 0, 'Both chains apply the same factor to different J columns: one rounded to three decimals, one at full precision. The 0.24 percent gap is the print''s rounding carried through the multiplication, not a physics or data difference.'),
  ('scal', 'intermediate', 'final', null, 21, 'What general rule does the Nameless Field rounding chain teach?', '["Always prefer the printed value, because published numbers are the authoritative record", "Always prefer full precision, because any rounding is an error that a careful analyst must eliminate from the record", "Round every intermediate result to three decimals so that independent chains stay comparable across publications", "Name which chain a number came from, because any value derived from a printed table carries the print''s rounding forever afterward"]'::jsonb, 3, 'Neither precision is wrong; they are different chains. Once a downstream value is built on a rounded print, the rounding is baked in, so the provenance must travel with the number, especially when tolerances are tight enough to tell the chains apart.'),
  ('scal', 'intermediate', 'final', null, 22, 'fitJPowerLaw on a single Ekene plug, with Swirr 0.25 supplied, returns which parameters?', '["a 0.3922841458642378 and b 0.17888262635639235", "a 0.25 and b 1, with r2Log 1", "a 0.21645 and b 0.25", "a 1 and b 0.25, with r2Log 1"]'::jsonb, 1, 'On collapsed, noise-free data with the correct Swirr the log-space fit recovers the designed power law exactly: a 0.25, b 1. The pair 0.3922841458642378 and 0.17888262635639235 is the Figure 4-18 fit, a different rock with a different shape.'),
  ('scal', 'intermediate', 'final', null, 23, 'The Fig 4-18 drainage reads fit to b 0.17888262635639235. What does a b that small say about the curve?', '["It is plateau-like: J changes little across the mid saturations and steepens only near Swirr", "It is nearly linear in saturation across the whole measured range, rising steadily from the plateau to the front", "It falls faster than the Ekene design curve at every saturation between the plateau and the front", "The fit failed to converge, so the exponent carries no meaning"]'::jsonb, 0, 'A small exponent means a gentle power law: a broad plateau with a steep front only near the irreducible saturation. The fit converged with r2Log 0.9548556748366249. The Ekene design carries b 1.0: shape is rock-dependent even though the collapse principle is general.'),
  ('scal', 'intermediate', 'final', null, 24, 'The Fig 4-18 power-law fit misses the figure reads by at most 0.027530745172516413 in J. Why is that acceptable?', '["Because the fit''s rmsLog is exactly zero on those points", "Because the figure''s own drainage curve is printed at only one decimal of precision on the J axis", "Because the reads were taken at a stated tolerance of 0.05 J, and the fit sits inside it", "Because J errors below 0.1 never matter in reservoir work, whatever the source of the curve being fitted"]'::jsonb, 2, 'The golden is a figure read, taken at a stated tolerance of plus or minus 0.05 J on the printed grid. A representation that stays within the read tolerance is faithful to the source; demanding more precision than the source carries would be false confidence.'),
  ('scal', 'intermediate', 'final', null, 25, 'averageJCurves combines samples with a geometric mean rather than an arithmetic mean. Why?', '["The geometric mean is faster to compute on a resampled grid", "The arithmetic mean would require equal sample counts at every saturation", "The geometric mean always sits below the arithmetic mean, which is conservative", "J is log-distributed, so averaging in log space respects the spread structure"]'::jsonb, 3, 'J values spread multiplicatively, so the natural average is taken in log space, which is the geometric mean. The routine also returns the min-max band so the analyst can see how far individual samples sit from the mean.'),
  ('scal', 'intermediate', 'final', null, 26, 'Without an explicit override, what does each sample''s Swirr default to in the averaging, and what is the risk?', '["Zero for every sample, which compresses the Sw* axis toward the origin", "Just below that sample''s lowest measured Sw, which distorts the Sw* axis when the true Swirr sits lower", "The mean of all samples'' lowest measured Sw values, which mixes the rocks together before normalization even starts", "0.25, the Ekene design value, which would be wrong for any other field"]'::jsonb, 1, 'The default is a data-driven convenience: each sample takes Swirr just below its own lowest measurement. If the true irreducible sits lower, the Sw* axis is distorted sample by sample. The refit r2Log is the tell, and the explicit override exists for exactly this case.'),
  ('scal', 'intermediate', 'final', null, 27, 'The Ekene design fits b 1.0 while the 1941 unconsolidated-sand curve fits b 0.17888262635639235. What does the comparison show?', '["Curve shape is rock-dependent even though the collapse principle applies within each rock family", "One of the two fits must be wrong, because the exponent b is a universal constant of the Leverett transform", "The 1941 curve was measured in a different unit system than the Ekene plugs", "The exponent b depends on which laboratory fluid system was used for the measurement, mercury reading higher than brine"]'::jsonb, 0, 'The J transform removes rock and fluid scaling, not shape. Different rock families keep their own J curves; what Leverett claims is that samples OF THE SAME rock family collapse together, not that all rocks share one exponent.'),
  ('scal', 'intermediate', 'final', null, 28, 'Besides the mean curve, what does averageJCurves return to help you judge the average?', '["A p-value testing the collapse hypothesis at each saturation grid point", "The arithmetic mean of the samples as a cross-check column", "A min-max band across the samples at each grid point, plus a power-law refit of the mean curve", "The list of samples it rejected as outliers, together with the reason each one failed"]'::jsonb, 2, 'Each grid point carries the geometric mean, the minimum, the maximum, and the sample count, and the mean curve is refit to a power law as the reservoir candidate. Nothing is silently rejected; judging the band is the analyst''s job.'),
  ('scal', 'intermediate', 'final', null, 29, 'The height gradient for the Ekene fluid pair is 0.07133527522935783 psi per ft. Which product builds it?', '["0.4335 times the brine gravity 1.03", "0.4335 times the oil specific gravity of 0.8654434250764526, taken by itself alone", "0.21645 times the density difference of the two fluids, converted into field units by the water gradient", "0.4335 times the difference between gammaW 1.03 and gammaO 0.8654434250764526"]'::jsonb, 3, 'Height conversion uses the fresh-water gradient 0.4335 psi per ft scaled by the specific-gravity CONTRAST, 1.03 minus 0.8654434250764526. Either fluid alone gives a column gradient, not the buoyancy contrast that lifts oil above the free water level.'),
  ('scal', 'intermediate', 'final', null, 30, 'The Ekene oil gravity used in the height conversion comes from the field''s locked API of 32. Which value is it?', '["0.8654434250764526, from 141.5 over (131.5 plus 32)", "0.32, the API gravity divided by one hundred", "1.03, which is the brine specific gravity", "0.865, read from a fluid-properties correlation chart"]'::jsonb, 0, 'Specific gravity follows exactly from API: 141.5 over (131.5 plus API). The chain is exact, not read from a chart, and the full value matters because the gradient and every height built on it inherit any rounding.'),
  ('scal', 'intermediate', 'final', null, 31, 'The Ekene entry pressure 0.7355825053402938 psi converts to which entry height?', '["10.31162356877775 m above the free water level", "3.142982863763458 ft above the free water level", "10.31162356877775 ft, or 3.142982863763458 m", "31.42982863763458 ft, from applying the metre conversion in the wrong direction"]'::jsonb, 2, 'Dividing 0.7355825053402938 psi by the gradient 0.07133527522935783 psi per ft gives 10.31162356877775 ft, and feet times 0.3048 gives 3.142982863763458 m. The wrong options swap or misapply the unit conversion, the classic hazard of a field-unit engine on a metric field.'),
  ('scal', 'intermediate', 'final', null, 32, 'The mapped Ekene contact sits at 1560 m and the free water level at 1563.1429828637636 m. What is the relationship?', '["The free water level is simply another name for the contact; the two terms are interchangeable in mapping work", "The contact is the top of the water-saturated rock; the FWL sits one entry height deeper", "The FWL sits above the contact because oil is lighter than water", "The 3.14 m offset is a datum shift error between the geoscience depth reference and the reservoir team''s depth reference"]'::jsonb, 1, 'Below the FWL capillary pressure is zero. Oil first appears one entry height above it, where Pc reaches the entry pressure, and that is the surface a log or a map picks as the contact. The offset here is exactly the entry height, 3.142982863763458 m.'),
  ('scal', 'intermediate', 'final', null, 33, 'At the crest of the Ekene column, 20.2818603515625 m above the contact, the model saturation is 0.35062979402484734. Why does this number matter to the booking?', '["The flat Sw of 0.35 in the booking is true at the crest only; every metre below sits wetter", "It proves the volumetric booking overstated the oil column by the full transition-zone thickness", "It shows the crest of the structure actually lies inside the water leg", "It equals the irreducible saturation, so the crest holds no movable water at all"]'::jsonb, 0, 'The saturation-height model drains the crest to almost exactly the booking''s flat 0.35, so the booking''s constant is the crest value, not a column average. The irreducible in the Pc model is 0.25, so the crest still sits above Swirr.'),
  ('scal', 'intermediate', 'final', null, 34, 'How high above the contact does the model saturation first fall to 0.5?', '["2.09532190917564 m", "12.571931455053829 m", "6.285965727526915 m", "8.643202875349512 m"]'::jsonb, 2, 'The transition ladder runs: Sw 0.7 at 2.09532190917564 m, Sw 0.5 at 6.285965727526915 m, Sw 0.45 at 8.643202875349512 m, and Sw 0.4 at 12.571931455053829 m above the contact. Each wrong option is a real rung of the ladder in the wrong role.'),
  ('scal', 'intermediate', 'final', null, 35, 'The engine returns saturation-height rows with h in feet while Ekene depths are metres. What is the exact conversion?', '["1 ft = 0.305 m, by industry convention", "1 m = 0.3048 ft", "1 ft = 0.33 m, close enough for column heights", "1 ft = 0.3048 m, exact by definition"]'::jsonb, 3, 'The international foot is defined as exactly 0.3048 m, so the conversion is exact, not approximate, and it points from feet to metres. Writing it backwards or rounding it moves every height in the chain.'),
  ('scal', 'intermediate', 'final', null, 36, 'Which single quantity lets a lab Pc curve measured on one plug predict reservoir Pc on different rock and fluids?', '["The normalized saturation Swn of the rel-perm system", "The dimensionless J value at each saturation", "The entry-pressure ratio between plug and reservoir", "The permeability ratio of the plug to the reservoir"]'::jsonb, 1, 'J strips the plug''s rock and fluid scaling out of Pc; multiplying by the reservoir''s own factor puts it back for the target rock. Neither a permeability ratio nor an entry-pressure ratio alone carries the full sigma cos theta and sqrt(k/phi) scaling.'),
  ('scal', 'intermediate', 'final', null, 37, 'The Ekene Pc model uses Swirr 0.25 while the rel-perm set uses Swc 0.35. How should you read the gap?', '["Both are real conventions: the Pc asymptote is the true irreducible, and the kr connate is what the crest drains to", "One of the two files carries a typo that must be corrected before use", "The Pc model was built for a different reservoir and was attached by mistake", "Swirr and Swc are the same physical quantity, so one of the files must be regenerated until the two values agree exactly"]'::jsonb, 0, 'The drainage asymptote and the connate saturation of a flow experiment answer different questions. The crest of this structure drains to about 0.35, which is where the kr set begins, while the Pc curve keeps falling toward its 0.25 asymptote far above the column.'),
  ('scal', 'intermediate', 'final', null, 38, 'Your Pc data refuses to follow a power law. Under the engine''s thin-real design, what is the supported route?', '["Fit a Thomeer hyperbola to the same data instead", "Use a tabulated J spec, interpolated log-linearly between rows", "Fit a Brooks-Corey lambda model with its own irreducible parameter", "Switch the analysis onto the imbibition branch of the measurement"]'::jsonb, 1, 'The owner lock keeps the module thin: no Thomeer, no Brooks-Corey machinery, no hysteresis. Data that will not power-law is carried as a table, and the evaluator interpolates log-J linearly between rows with clamped ends.'),
  ('scal', 'intermediate', 'final', null, 39, 'Order the Professional workflow correctly.', '["Convert to height first, then compute J, then collect the lab Pc tables, then rescale", "Average the samples first, then measure lab Pc, then compute J, then convert to height", "Compute reservoir Pc first, then J, then validate the lab tables, then average", "Lab Pc to J, fit or average the samples, rescale to reservoir Pc, then saturation versus height"]'::jsonb, 3, 'The chain runs one way: validated lab tables become dimensionless J curves, the curves are fitted or averaged into one spec, the spec is rescaled to the reservoir rock, and only then do gravities turn pressure into height above the free water level.'),
  ('scal', 'intermediate', 'final', null, 40, 'A new plug''s J curve rides well above the field cloud with the same shape. What is the FIRST thing to check?', '["Whether the plug was cut from inside the transition zone", "Whether the laboratory accidentally ran the imbibition branch instead of drainage on this particular plug", "The reservoir temperature during the laboratory measurement, which changes the interfacial tension of the pair", "The typed rock properties, since a k or phi error shifts the whole curve by sqrt(k/phi)"]'::jsonb, 3, 'A uniform vertical shift with preserved shape is the signature of a scaling error, and the rock enters only through sqrt(k/phi). A genuinely different rock or a wrong branch changes the shape, not just the level.'),
  ('scal', 'intermediate', 'final', null, 41, 'Why does a non-zero entry pressure force the free water level and the mapped contact apart?', '["Oil cannot enter the rock until Pc reaches the entry value, and Pc only reaches it some height above the FWL", "Because the contact is picked on well logs while the free water level is interpreted from seismic and pressure data", "Because brine salinity, and therefore brine density, increases with depth", "Because the mapping grid smooths the picked contact upward structurally"]'::jsonb, 0, 'Pc grows linearly with height above the FWL at the fluid-contrast gradient. The rock stays fully water saturated until Pc reaches the entry pressure, so the first oil appears one entry height up: 3.142982863763458 m on the Ekene sand.'),
  ('scal', 'intermediate', 'final', null, 42, 'The book prints J at Sw 0.2 as 0.169 and the engine holds 0.16939891980544033. A colleague calls the engine wrong. What is the correct reading?', '["The engine is wrong: published values define the truth for a golden fixture", "The book is wrong: three decimals is too coarse for engineering use", "Both state one measurement at different precision; the discipline is knowing which one a downstream number was built from", "Neither number can be used until the owner supplies the original Trans. AIME 142 scan for a re-read at full plate scale"]'::jsonb, 2, 'The print is the engine value rounded for publication. Downstream, the two chains give reservoir Pc values that differ by 0.24 percent, so the discipline is provenance, not a verdict on which precision is morally right.');
